import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the billboard plane
  const group = new THREE.Group();

  // Atlas region dimensions (512x320 from spec)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight;

  // Create plane geometry sized to atlas aspect ratio
  // Use a reasonable scene unit size (headline context ~2.5 units wide)
  const planeWidth = 2.5;
  const planeHeight = planeWidth / aspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load the ceramic grain texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Configure texture for the atlas region
    texture.flipY = false;

    // Adjust UV coordinates for atlas region (top-left 512x320 of a larger atlas)
    // Assuming a standard atlas layout; offset is 0,0 so no UV offset needed
    const uvAttribute = geometry.getAttribute('uv');
    // Atlas region: (0, 0, 512, 320) — if atlas is 2048x2048, that's (0,0) to (0.25, 0.15625)
    // For now, assume full texture use since only region specified is entire source
    uvAttribute.needsUpdate = true;

    // Create material with texture node
    const material = new MeshBasicNodeMaterial({
      colorNode: texture,
      side: THREE.DoubleSide,
      transparent: true,
      depthTest: true,
      depthWrite: true,
    });

    const plane = new THREE.Mesh(geometry, material);

    // Billboard toward camera (will be handled by adapter positioning)
    plane.castShadow = false;
    plane.receiveShadow = false;

    group.add(plane);
  });

  // Create headline text via fontAtlas
  // "Features" as a display-size headline (96px → scene scale ~0.34 em height per spec)
  // Display role, serif (Lora), 400 weight, paper color (#e8ecf2)
  const textObj = ctx.fontAtlas.createText('Features', {
    fontSize: 96,
    color: '#e8ecf2',
    align: 'center',
  });

  // Position text below the textured plane
  textObj.position.y = -planeHeight / 2 - 0.4;
  textObj.position.z = 0.01; // Slight z offset to sit in front

  group.add(textObj);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    // Material and texture are disposed by Three.js when group is removed
    // GSAP timelines: none active for this static node
  };

  group.userData.handlers = {};

  return group;
}
